const neuronPartes=[{"desc":"El acto concreto que se quiere hacer, escrito en una línea","ans":"Qué se quiere hacer","opts":["Qué se quiere hacer","Qué lo regula","Quién lo emite","Qué vigencia tiene"]},{"desc":"La respuesta a dónde está escrito ese requisito","ans":"Qué lo regula","opts":["Qué lo regula","Qué requisitos pide","Dónde queda la copia","Cuánto tarda y cuánto cuesta"]},{"desc":"La oficina cuyo cargo firma y sella el papel","ans":"Quién lo emite","opts":["Quién lo emite","Qué se quiere hacer","Qué vigencia tiene","Qué lo regula"]},{"desc":"La lista de lo que hay que llevar, pedida completa y por escrito","ans":"Qué requisitos pide","opts":["Qué requisitos pide","Quién lo emite","Dónde queda la copia","Qué se quiere hacer"]},{"desc":"Los días de espera y los lempiras que hay que poner","ans":"Cuánto tarda y cuánto cuesta","opts":["Cuánto tarda y cuánto cuesta","Qué vigencia tiene","Qué lo regula","Qué requisitos pide"]},{"desc":"La fecha en que el papel deja de servir","ans":"Qué vigencia tiene","opts":["Qué vigencia tiene","Cuánto tarda y cuánto cuesta","Dónde queda la copia","Quién lo emite"]},{"desc":"El sello y la fecha de quien recibió, guardados en la carpeta del centro","ans":"Dónde queda la copia","opts":["Dónde queda la copia","Qué requisitos pide","Qué lo regula","Qué se quiere hacer"]},{"desc":"La carpeta con los papeles listos antes de que los pidan","ans":"El expediente del proyecto","opts":["El expediente del proyecto","La hoja de seguimiento","Dónde queda la copia","Qué requisitos pide"]}];
let neuronIdx=0,neuronDone=false;
function showNeuron(){neuronDone=false;if(neuronIdx>=neuronPartes.length){const el=document.getElementById('neuronDesc');if(el)el.textContent='🎉 ¡Todos los conceptos identificados!';const opts=document.getElementById('neuronOpts');if(opts)opts.innerHTML='';fin('s-widgets');return;}const d=neuronPartes[neuronIdx];const prog=document.getElementById('neuronProg');if(prog)prog.textContent=`Concepto ${neuronIdx+1} de ${neuronPartes.length}`;const desc=document.getElementById('neuronDesc');if(desc)desc.textContent=d.desc;const opts=document.getElementById('neuronOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='cmp-opt';b.textContent=opt;b.onclick=()=>checkNeuron(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbNeuron');if(fbEl)fbEl.classList.remove('show');}
function checkNeuron(opt,btn,d){if(neuronDone)return;neuronDone=true;document.querySelectorAll('#neuronOpts .cmp-opt').forEach(b=>{if(b.textContent===d.ans)b.classList.add('correct');else if(b===btn&&b.textContent!==d.ans)b.classList.add('wrong');});const isOk=opt===d.ans;if(isOk){fb('fbNeuron','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('neuron_'+neuronIdx)){xpTracker.wgt.add('neuron_'+neuronIdx);pts(3);}sfx('ok');}else{fb('fbNeuron','La respuesta correcta es: '+d.ans,false);sfx('no');}}
function nextNeuron(){sfx('click');neuronIdx++;showNeuron();}
function resetNeuron(){sfx('click');neuronIdx=0;showNeuron();}

