const neuroPairs=[{"trans":"Usar las misiones en dos secciones de sexto, con el sí de palabra de la directora","func":"Un permiso por escrito del centro, con las secciones y el horario","opts":["Un permiso por escrito del centro, con las secciones y el horario","Un aval del distrito antes de pisar el centro","Una constancia firmada por el proyecto","Un convenio con la Secretaría"]},{"trans":"Justificar ante la ferretería los 8.000 lempiras que aportó","func":"Una constancia del proyecto con fecha, monto y en qué se usó","opts":["Una constancia del proyecto con fecha, monto y en qué se usó","Un recibo emitido por el centro educativo","Un permiso de la oficina del distrito","Una carta de entendimiento con la ferretería"]},{"trans":"Cobrar 150 lempiras al mes a un centro que paga con cheque","func":"Un recibo numerado, y antes preguntar con qué documento pueden pagar","opts":["Un recibo numerado, y antes preguntar con qué documento pueden pagar","Una constancia de donación al centro","Un aval del distrito para poder cobrar","Un convenio de tres años con el centro"]},{"trans":"Recibir quince tabletas de una ONG, sin dinero de por medio","func":"Una carta de entendimiento que diga también qué no incluye","opts":["Una carta de entendimiento que diga también qué no incluye","Un convenio que obligue a las dos partes","Un recibo por los 90.000 lempiras de las tabletas","Un permiso del patronato del centro"]},{"trans":"Publicar la foto de una sección de treinta niños","func":"Un permiso por familia, para esa publicación y no para siempre","opts":["Un permiso por familia, para esa publicación y no para siempre","El permiso de la maestra que tomó la foto","Una constancia del centro educativo","El aval del distrito para publicar"]}];
let neuroIdx=0,neuroDone=false;
function showNeuro(){neuroDone=false;if(neuroIdx>=neuroPairs.length){const el=document.getElementById('neuroTrans');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('neuroOpts');if(opts)opts.innerHTML='';return;}const d=neuroPairs[neuroIdx];const prog=document.getElementById('neuroProg');if(prog)prog.textContent=`${neuroIdx+1} de ${neuroPairs.length}`;const trans=document.getElementById('neuroTrans');if(trans)trans.textContent=d.trans;const opts=document.getElementById('neuroOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkNeuro(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbNeuro');if(fbEl)fbEl.classList.remove('show');}
function checkNeuro(opt,btn,d){if(neuroDone)return;neuroDone=true;document.querySelectorAll('#neuroOpts .qz-opt').forEach(b=>{if(b.textContent===d.func)b.classList.add('correct');else if(b===btn&&b.textContent!==d.func)b.classList.add('wrong');});const isOk=opt===d.func;if(isOk){fb('fbNeuro','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('neuro_'+neuroIdx)){xpTracker.wgt.add('neuro_'+neuroIdx);pts(3);}sfx('ok');}else{fb('fbNeuro','Correcto: '+d.func,false);sfx('no');}setTimeout(()=>{neuroIdx++;showNeuro();},1800);}
function resetNeuro(){sfx('click');neuroIdx=0;showNeuro();}

