// ===================== TASK GENERATOR =====================
const identifyTaskDB=[{"s":"La oficina cuyo cargo firma y sella el papel.","type":"Emisor"},{"s":"Desde cuándo y hasta cuándo vale un papel.","type":"Vigencia"},{"s":"Deja hacer algo concreto, en un lugar y por un tiempo.","type":"Permiso"},{"s":"Prueba que algo pasó, con fecha y con quien lo emite.","type":"Constancia"},{"s":"Una autoridad respalda a alguien ante otros.","type":"Aval"},{"s":"Dos partes escriben qué hace cada una, sin dinero de por medio.","type":"Carta de entendimiento"},{"s":"Obliga a las dos partes y por eso se lee dos veces.","type":"Convenio"},{"s":"Prueba que se pagó, con monto, fecha y a nombre de quién.","type":"Recibo"},{"s":"La copia de lo entregado, con sello y fecha de quien recibió.","type":"Acuse"},{"s":"El resumen de lo hablado, mandado el mismo día.","type":"Correo de confirmación"}];
const classifyTaskDB=[{"w":"Permiso de uso en aula","gen":"Permiso","n":"Con secciones y horario","g":"Lo emite el centro","t":"Deja entrar con el material"},{"w":"Aval del distrito","gen":"Aval","n":"Autoriza y no obliga","g":"Lo emite el nivel de arriba","t":"Abre varios centros de una vez"},{"w":"Constancia para el patrocinador","gen":"Constancia","n":"Fecha, monto y destino","g":"La emite el proyecto","t":"Prueba en qué se usó lo aportado"},{"w":"Recibo del cobro mensual","gen":"Recibo","n":"Numerado desde el primero","g":"Lo emite el proyecto","t":"Prueba que el centro pagó"},{"w":"Carta con la ONG de las tabletas","gen":"Carta de entendimiento","n":"Sin dinero de por medio","g":"La firman las dos partes","t":"Dice qué pone cada uno y qué no incluye"},{"w":"Acuerdo de autoría y uso","gen":"Convenio","n":"Cede el uso, no la autoría","g":"Lo firman las dos partes","t":"Fija qué se cede y por cuánto tiempo"},{"w":"Permiso de foto por familia","gen":"Permiso","n":"Por niño y por publicación","g":"Lo emite la familia","t":"Autoriza esa publicación y no otra"},{"w":"Correo de confirmación","gen":"Correo","n":"Mandado el mismo día","g":"Lo manda el proyecto","t":"Deja constancia de lo hablado"},{"w":"Copia sellada de la solicitud","gen":"Acuse","n":"Sello, firma y fecha","g":"Lo devuelve quien recibe","t":"Prueba que se entregó y cuándo"},{"w":"Hoja de seguimiento","gen":"Instrumento propio","n":"Once campos, cinco antes de ir","g":"La lleva el proyecto","t":"Evita que el trámite se abandone"}];
const completeTaskDB=[{"s":"La oficina que firma y sella el papel es el ___.","opts":["solicitante","emisor","testigo"],"ans":"emisor"},{"s":"Desde cuándo y hasta cuándo vale un papel es su ___.","opts":["formato","sello","vigencia"],"ans":"vigencia"},{"s":"El papel que deja hacer algo concreto es el ___.","opts":["permiso","recibo","aval"],"ans":"permiso"},{"s":"El papel que prueba que algo ya pasó es la ___.","opts":["solicitud","constancia","carta"],"ans":"constancia"},{"s":"La copia con sello y fecha de quien recibió es el ___.","opts":["borrador","duplicado","acuse"],"ans":"acuse"},{"s":"Lo que nadie puede enseñar por escrito es una ___.","opts":["costumbre","norma","circular"],"ans":"costumbre"},{"s":"De las fichas se cede el ___, nunca la autoría.","opts":["nombre","uso","crédito"],"ans":"uso"},{"s":"Ante un requisito nuevo se pregunta dónde está ___.","opts":["firmado","sellado","escrito"],"ans":"escrito"}];
const explainQuestions=[{"q":"En la ventanilla te piden un requisito que no esperabas. ¿Cómo averiguas si es norma escrita, costumbre de la oficina o invento de una persona, y qué haces con cada uno?","ans":"Se averigua con una sola pregunta, hecha sin levantar la voz: «¿dónde puedo leerlo?». Si hay documento, se pide copia o el nombre exacto y se cumple sin discutir, porque discutir una norma de verdad solo demuestra que uno no la leyó. Si no hay documento, puede ser la costumbre de esa oficina o el invento de una persona, y en los dos casos se cumple igual, porque pelearlo de frente cuesta más que hacerlo. Lo que cambia es lo que se anota: quién lo pidió, con qué cargo y en qué fecha, y si se puede, un correo del mismo día pidiendo que confirmen lo que dijeron. Eso sirve para dos cosas. Para no heredar el requisito el año que viene, cuando esa persona ya esté en otro escritorio y nadie lo pida. Y para saber, cuando el trámite se atrasa, si el atraso viene de la norma o de una costumbre que se puede conversar."},{"q":"Explica por qué el emisor de un papel es una oficina y no una persona, y qué se anota entonces de la persona que atiende.","ans":"El emisor es el cargo que firma y sella, y ese cargo sigue emitiendo aunque la persona cambie de escritorio en marzo. Si el trámite se apoya en que «el ingeniero es amigo», el día que trasladan al ingeniero el trámite empieza otra vez desde cero y el proyecto se queda sin nada en la mano. Por eso la primera pregunta es qué oficina emite este papel, y la segunda es si esa oficina emite o solo recomienda: quien recomienda ayuda, y su carta no abre ninguna puerta por sí sola. Ahora bien, de la persona que atiende sí se anota todo: nombre, cargo y fecha de la conversación, y se le confirma por escrito lo que dijo, aunque sea con un correo de tres líneas. No es desconfianza, es memoria. Dentro de seis meses, cuando alguien diga que ese requisito nunca se pidió, esas tres líneas son lo único que queda."},{"q":"Explica qué es la vigencia de un papel y por qué en M.E.T.A.S casi todo se vuelve a sacar en febrero.","ans":"La vigencia es desde cuándo y hasta cuándo vale un papel, y se pregunta al emitirlo, no el día que se necesita. Un papel sin fecha es una foto vieja: en la ventanilla lo miran, ven que es de hace tres años y ya no lo reconoce nadie, aunque en su momento fuera perfectamente válido. En este proyecto la vigencia real de casi todo es el año lectivo, aunque eso no esté escrito en ninguna parte: un aval del año escolar se muere en noviembre, y en febrero hay que sacarlo otra vez. Por eso el mismo trámite hecho en enero rinde por todo el año y hecho en septiembre no rinde nada. Lo que se hace con eso es simple: se apunta en el expediente desde cuándo y hasta cuándo, y se pone un recordatorio dos meses antes de que venza, para que la renovación caiga en una semana tranquila y no el día del taller."},{"q":"Una directora te dice que sí a un taller para 40 maestras y quedó en conseguir el aval. ¿Qué haces ese mismo día y por qué?","ans":"Ese mismo día se manda un correo de confirmación, antes de que se enfríe la reunión y antes de imprimir un solo papel. Empieza con «para dejar constancia de lo que hablamos hoy», lista lo acordado en puntos, dice quién hace qué y con qué fecha, y termina pidiendo que corrijan si algo quedó distinto. No lo pide nadie, no es un papel oficial y toma cinco minutos. Sirve para tres cosas: deja por escrito que ella pide el aval y no uno; fija la fecha, que es lo que después se discute; y si el día del taller aparece un requisito nuevo, hay algo con qué comparar. Lo que no se hace ese día es imprimir. Mientras el aval no esté, se preparan 20 fichas de prueba y nada más, porque el sí de una persona es verdadero y no siempre alcanza: quien autoriza en su centro no autoriza una actividad con docentes de varios centros."},{"q":"Una institución quiere adoptar tus fichas e imprimir 5.000 ejemplares. ¿Qué se cede, qué no se cede nunca y cuándo se escribe?","ans":"Se cede el uso, y acotado: imprimir y repartir en sus centros, durante un tiempo definido y para ese fin. No se cede la autoría, ni el derecho a modificar el contenido sin consultar, ni el de venderlo, ni el de quitar el crédito, y el crédito va impreso en cada ejemplar, no en una lista de agradecimientos al final. Eso se escribe antes de entregar el archivo, y ahí está todo el asunto: mientras el archivo no ha salido, uno tiene algo que la otra parte quiere, y por eso se puede pedir que quede claro. Después de entregarlo ya no hay con qué negociar, y lo adoptado sin acuerdo tiende a quedarse sin nombre, no por mala fe sino porque nadie se acuerda de preguntar. Cinco mil ejemplares son alcance y legitimidad de verdad, así que la respuesta es que sí, con esa condición escrita."},{"q":"Explica el expediente del proyecto y la hoja de seguimiento: qué es cada uno, en qué se diferencian y cuándo se llenan.","ans":"El expediente del proyecto en una hoja es una tabla con una fila por papel y siete columnas: qué papel, quién lo emite, qué pide, cuánto tarda y cuánto cuesta, vigencia desde y hasta, dónde está la copia, y estado. En estado solo caben tres palabras: listo, pedido o falta. Es la foto de lo que se tiene, y se revisa en enero, antes de que empiece el año lectivo. La idea de fondo es que el expediente son los papeles listos antes de que los pidan: quien los tiene entra, quien los va a buscar pierde el año escolar. La hoja de seguimiento es otra cosa: es una hoja por cada trámite que está en curso, con once campos, y los cinco primeros se llenan hoy, antes de pisar ninguna oficina. Si no se pueden llenar, ya se sabe cuál es la primera pregunta que hay que ir a hacer. Y el campo once, el próximo paso con fecha y con el nombre de quien lo hace, nunca se deja en blanco: un trámite sin próximo paso con fecha es un trámite abandonado."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

