function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Una directora dice que sí a que las misiones se usen en dos secciones de sexto y pide empezar el lunes. Imprimir las 120 fichas cuesta 480 lempiras y el taller para las maestras son dos horas de un sábado."},{"txt":"Catorce centros del mismo distrito quieren el material, y visitarlos uno por uno son catorce permisos y unos 600 lempiras de transporte por vuelta."},{"txt":"Una ferretería aporta 8.000 lempiras para imprimir fichas y pide una constancia para justificar el gasto en su contabilidad. El proyecto nunca ha emitido una."},{"txt":"Veinte aulas a 150 lempiras al mes son 3.000 lempiras mensuales y 36.000 al año, y el primer centro pregunta a nombre de quién hace el cheque."},{"txt":"Una institución quiere adoptar las fichas e imprimir 5.000 ejemplares para sus centros, unos 60.000 lempiras de impresión que no pone el proyecto. En la reunión nadie habló de autoría."},{"txt":"Una ONG ofrece quince tabletas valoradas en 90.000 lempiras para tres centros, sin dinero de por medio, y quiere «algo firmado» para su informe."},{"txt":"Hay una foto muy buena de una sección usando las misiones y se quiere publicar: son 30 niños, 30 permisos de familia y unos 300 lempiras de transporte en dos visitas al centro. No hay ningún papel firmado."},{"txt":"Un centro reclama 12.000 lempiras de perjuicio por 150 fichas que dice que faltaron, y existe un correo de hace cuatro meses, del mismo día de la reunión, que dice exactamente qué se acordó."}];
const critCaseQuestions=["1. ¿Qué papel hace falta aquí y cómo se llama en la práctica?","2. ¿Quién lo emite, y esa oficina emite o solo recomienda?","3. ¿Está escrito o es costumbre, y cómo lo averiguas sin pelear?","4. ¿Qué vigencia debe tener y dónde va a quedar la copia?"];
const critCaseGuides=["Se nombra el documento, no la intención: no «apoyo» ni «permiso» en general, sino permiso de uso en aula, aval, constancia, recibo, carta de entendimiento o convenio. Y el nombre exacto se confirma en la oficina que lo emite: esa consulta es parte del trámite, no un paso previo.","Una oficina, no una persona simpática. Vale la pena separar emitir de recomendar: quien recomienda ayuda y no firma, y su carta no abre ninguna puerta sola. Si no se puede decir qué cargo firma, todavía no se está decidiendo: se está adivinando.","La pregunta buena es siempre alguna forma de «¿dónde puedo leerlo?», hecha sin levantar la voz. Si hay documento, se cumple sin discutir. Si no lo hay, se cumple igual y se anota quién lo pidió, con qué cargo y en qué fecha.","Desde cuándo y hasta cuándo, con recordatorio dos meses antes de que venza. Y la copia sellada en la carpeta del centro, con la fecha en el nombre del archivo; si no sellan, el correo del mismo día. Sin copia, el trámite se repite entero el año que viene."];

const critErrorBank=[{"txt":"\"La directora ya dijo que sí, mando a imprimir las 120 fichas hoy mismo\".","g1":"El sí de palabra es verdadero y no es un papel: la persona cambia de escritorio, y en la puerta pueden pedir algo que ella nunca mencionó. Los 480 lempiras se pierden completos.","g2":"Se le piden tres líneas por escrito con las secciones y el horario, aunque sea un correo. Con eso se imprime; sin eso, se imprimen 20 fichas de prueba y nada más."},{"txt":"\"Me piden la carta en letra de molde y con tres copias, así que hay que hacerlo y ya\".","g1":"Puede ser norma, costumbre o invento de una persona, y no da lo mismo: lo que se inventó una persona se va con ella, y el año que viene nadie lo pide.","g2":"Se cumple, y de paso se pregunta sin pelear «¿dónde puedo leerlo?». Se anota quién lo pidió y cuándo, para no heredar el requisito para siempre."},{"txt":"\"Como voy a trabajar en catorce centros, primero saco el aval de arriba y después aviso abajo\".","g1":"Un aval que llega antes que la conversación se lee abajo como una orden, y una orden que no se quiso se cumple mal: el papel entra y el proyecto no.","g2":"Primero se habla con dos o tres directores; después se pide el aval, y el papel dice que autoriza y que no obliga, para que cada centro decida si entra."},{"txt":"\"El de la ventanilla dijo que sí se puede, así que ya está\".","g1":"Quien atiende casi nunca es quien emite: puede orientar, recomendar o equivocarse, y su palabra no sostiene nada dentro de seis meses.","g2":"Se anota su nombre y su cargo, y se confirma por escrito lo que dijo, aunque sea con un correo de tres líneas del mismo día."},{"txt":"\"El aval lo sacamos el año pasado, sirve igual\".","g1":"Todo papel tiene vigencia, y el del año escolar se muere en noviembre. Además, un cambio de titular lo acorta en la práctica aunque la fecha diga otra cosa.","g2":"Se apunta desde cuándo y hasta cuándo vale, con recordatorio dos meses antes, y lo del año escolar se vuelve a sacar en febrero."},{"txt":"\"Entregué la solicitud en la oficina; no me dieron nada, pero ahí quedó\".","g1":"Sin copia sellada no hay nada que reclamar. Es el único trámite que no se puede rehacer, porque el papel ya salió de las manos de uno.","g2":"Se pide acuse: sello, firma y fecha en la copia. Si no sellan, se manda el mismo día un correo diciendo qué se entregó, a quién y cuándo, y se guarda en la carpeta del centro."}];

const critDecisionBank=["El sí de la directora alcanza para meter las misiones de M.E.T.A.S en dos secciones de sexto y 480 lempiras impresos, ¿o hace falta un papel de más arriba? ¿Qué se pide, a quién y antes de qué?","Catorce centros y un solo papel: ¿la oficina a la que vas emite el aval o solo recomienda, y qué tiene que decir ese papel para no quemar el proyecto en el aula?","La ferretería aporta 8.000 lempiras y pide constancia: ¿quién la emite, qué dice exactamente y qué se adjunta para poder demostrarlo?","Veinte aulas a 150 lempiras al mes: ¿se cobra como persona o como organización, y cuál de las dos puede pagar el centro?","Cinco mil ejemplares de las fichas de M.E.T.A.S impresos por una institución: ¿qué se cede exactamente, qué no se cede nunca y en qué momento se escribe?","Las quince tabletas de 90.000 lempiras: ¿carta de entendimiento o convenio, y qué va en el apartado de qué no incluye?","Treinta niños en la foto y ningún papel: ¿quién emite ese permiso, para qué uso concreto, y qué se publica mientras tanto?","Nadie pidió que quedara nada por escrito de la reunión: ¿qué se manda hoy mismo, con qué palabras y dónde se guarda?"];
const critDecisionGuide="En cada decisión, escribe primero qué papel hace falta y quién lo emite; después, si eso está escrito o es costumbre; después qué vigencia debe tener y dónde va a quedar la copia. Casi ninguna decisión es sí o no: casi todas son sí con la condición de que quede algo escrito, con fecha y con nombre de quien lo firma. Si no puedes decir quién emite el papel, todavía no estás decidiendo: estás adivinando, y esa es la primera pregunta que hay que ir a hacer.";

const critCompareBank=[{"a":"Pedir un permiso de uso en aula, con secciones y horario.","b":"Pedir una constancia de que el taller se dio.","ga":"Caso A: es el papel que deja hacer algo concreto, y por eso se pide antes. Sin él, el trabajo se hace y se pierde en la puerta.","gb":"Caso B: prueba que algo ya pasó, y por eso se pide después. Sirve para el expediente y para el patrocinador, no para entrar."},{"a":"Firmar una carta de entendimiento con la ONG de las tabletas.","b":"Firmar un convenio con la ONG de las tabletas.","ga":"Caso A: no hay dinero de por medio, así que basta escribir qué pone cada uno, qué no incluye y hasta cuándo dura.","gb":"Caso B: obliga a las dos partes, y obligaría a dar soporte a quince aparatos que el proyecto no puede sostener. Se lee dos veces y se firma en frío."},{"a":"Un requisito que la oficina puede enseñar en un documento.","b":"Un requisito que solo existe en la boca de quien atiende.","ga":"Caso A: se cumple sin discutir y se puede leer antes de ir, así que no hay sorpresas en la ventanilla.","gb":"Caso B: se cumple igual, pero se anota quién lo pidió y cuándo, porque el año que viene puede no pedirlo nadie y no conviene heredarlo."},{"a":"Quedarse con la copia sellada de lo entregado.","b":"Quedarse con la promesa de que «ahí quedó».","ga":"Caso A: aguanta un cambio de funcionario, una mudanza de oficina y cuatro meses de olvido. Es lo único que sostiene un reclamo de 12.000 lempiras.","gb":"Caso B: no sobrevive al primer traslado. Cuando el papel se pierde, el trámite se repite entero y el año escolar ya no espera."}];

const critCauseBank=[{"cause":"Se imprime y se prepara el material antes de preguntar qué papel hace falta.","guide":"El trabajo entero queda a merced de un requisito que nadie mencionó. Una llamada de cinco minutos antes de imprimir vale 1.200 lempiras y tres semanas."},{"cause":"Se le pide el papel a quien solo puede recomendar.","guide":"Pasan las semanas y no sale nada, porque esa oficina nunca pudo emitirlo. La pregunta que faltó es si emite o solo recomienda."},{"cause":"Se cumple como norma un requisito que se inventó una persona.","guide":"Se rehace el trabajo tres veces y el requisito se hereda: al año siguiente se vuelve a hacer igual, aunque quien lo pidió ya no esté."},{"cause":"Se entrega la solicitud sin quedarse con copia sellada.","guide":"El día que la oficina dice que nunca la recibió no hay con qué contestar. Es el único trámite que no se puede rehacer."},{"cause":"Nadie apuntó la vigencia del aval ni puso recordatorio.","guide":"En septiembre el papel ya no sirve, el taller se cae y hay que empezar el trámite en la peor semana del año."},{"cause":"Se entrega el archivo de las fichas sin escribir qué se cede.","guide":"Lo adoptado sin acuerdo tiende a quedarse sin nombre. Después de entregar ya no hay con qué negociar el crédito impreso."}];
const critEffectBank=[{"effect":"El taller se dio en la fecha prometida y sin sustos en la puerta.","guide":"Se preguntó antes de imprimir qué papel hacía falta y quién lo emitía, y las 300 fichas salieron cuando ya había fecha segura."},{"effect":"Catorce centros abrieron la puerta con un solo papel y ninguno se sintió obligado.","guide":"El aval se pidió después de hablar con dos o tres directores, y decía que autoriza y que no obliga. Cada centro decidió si entraba."},{"effect":"La ferretería repitió su aporte al año siguiente.","guide":"La constancia decía qué se recibió, para qué se usó y en qué fecha, con la copia de la factura de la imprenta. Lo que se puede demostrar se puede repetir."},{"effect":"Un reclamo de 12.000 lempiras se cerró en una tarde.","guide":"Había un correo del mismo día de la reunión con lo acordado en puntos. No lo pidió nadie y fue la única prueba que quedó."},{"effect":"En febrero el proyecto ya estaba trabajando mientras otros empezaban a pedir permisos.","guide":"El expediente se revisó en enero y los papeles del año se sacaron entonces. El trámite hecho en enero vale por todo el año."},{"effect":"Las fichas se imprimieron en 5.000 ejemplares con el crédito del autor en cada uno.","guide":"Se escribió antes de entregar el archivo qué se cedía (el uso, acotado) y qué no se cedía nunca: autoría, venta, modificación y crédito."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`📜 El papel que falta · Forma ${cf} · Normas y trámites · Ruta del Poder Político`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué papel hace falta aquí, quién lo emite y con qué condición por escrito seguirías adelante? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El papel que falta: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué papel hace falta aquí, quién lo emite y con qué condición por escrito seguirías adelante? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El papel que falta Normas y trámites · Ruta del Poder Político · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El papel que falta · Normas y trámites · Ruta del Poder Político · Autocapacitación Técnica</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El papel que falta · Normas y trámites · Ruta del Poder Político · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🎯","label":"Qué se quiere hacer","text":"¿Qué acto concreto se quiere hacer? <strong>Decide:</strong> qué papel hace falta y ninguno más. <strong>Se rompe:</strong> al pedir «apoyo» o «permiso» en general, que nadie sabe cómo firmar. <strong>En M.E.T.A.S:</strong> no es «entrar al sistema educativo», es «dar un taller de dos horas a las maestras de una escuela»."},{"y":"2","icon":"📖","label":"Qué lo regula","text":"¿Esto está escrito en algún lado o es la costumbre de esta oficina? <strong>Decide:</strong> si el requisito se cumple o se conversa. <strong>Se rompe:</strong> al obedecer inventos personales y al discutir normas de verdad. <strong>En M.E.T.A.S:</strong> casi nada de lo que piden está escrito, y por eso se pregunta con calma dónde lo dice."},{"y":"3","icon":"🏢","label":"Quién lo emite","text":"¿Qué oficina firma este papel? <strong>Decide:</strong> adónde se va y con quién se habla. <strong>Se rompe:</strong> al pedirle a quien solo puede recomendar, no emitir. <strong>En M.E.T.A.S:</strong> el permiso de aula lo da el centro; el aval para varios centros, el nivel de arriba."},{"y":"4","icon":"📋","label":"Qué requisitos pide","text":"¿Qué hay que llevar exactamente? <strong>Decide:</strong> cuánto trabajo hay antes de ir. <strong>Se rompe:</strong> cuando el requisito aparece en la ventanilla y hay que volver otro día. <strong>En M.E.T.A.S:</strong> se pide la lista completa por escrito antes de mover un dedo."},{"y":"5","icon":"⏳","label":"Cuánto tarda y cuánto cuesta","text":"¿Cuántos días y cuántos lempiras? <strong>Decide:</strong> si el plan cabe en el calendario escolar. <strong>Se rompe:</strong> al no preguntar el tiempo y prometer una fecha imposible. <strong>En M.E.T.A.S:</strong> entre el sí de palabra y el papel firmado pasan semanas, y hay que contarlas."},{"y":"6","icon":"📅","label":"Qué vigencia tiene","text":"¿Hasta cuándo vale este papel? <strong>Decide:</strong> cuándo toca repetir el trámite. <strong>Se rompe:</strong> al creer que lo firmado una vez vale para siempre. <strong>En M.E.T.A.S:</strong> un aval del año escolar se muere en noviembre y en febrero hay que sacarlo otra vez."},{"y":"7","icon":"🗄️","label":"Dónde queda la copia","text":"¿Dónde va a estar este papel dentro de un año? <strong>Decide:</strong> si el trámite se repite o se hereda. <strong>Se rompe:</strong> sin copia sellada, que es el único trámite que no se puede rehacer. <strong>En M.E.T.A.S:</strong> una carpeta por centro, con la fecha en el nombre del archivo."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">📞</span><span class="ms-text"><strong>Llamaste al distrito antes de imprimir:</strong> cinco minutos de llamada descubren el aval que nadie había mencionado, y quedan dos semanas para sacarlo.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📜</span><span class="ms-text"><strong>El taller se hace, tarde pero se hace:</strong> las 300 fichas se imprimen cuando ya hay fecha segura y papel en la mano.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🖨️</span><span class="ms-text"><strong>Te pusiste a imprimir con el sí del director:</strong> ese sí era verdadero y no alcanzaba, porque él autoriza en su centro y no una actividad con docentes de varios centros.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">💸</span><span class="ms-text"><strong>La cuenta del día:</strong> 1.200 lempiras impresos y tres semanas de trabajo perdidos por no hacer una pregunta de cinco minutos.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"norma":{"nombre":"Qué lo regula","icon":"📖","estructura":{"title":"Qué es","info":"• La respuesta a <strong>¿dónde está escrito esto?</strong><br>• Tres cosas distintas: la norma, la práctica y el invento personal<br>• Confundirlas cuesta meses de trabajo"},"funcion":{"title":"Cómo se averigua","info":"• Se pregunta sin pelear: <strong>«¿dónde puedo leerlo?»</strong><br>• Si hay documento, se pide copia o el nombre exacto<br>• Si no hay, se pide por correo lo que le dijeron a uno"},"enfermedades":{"title":"Dónde se traba","info":"• Con el requisito que se inventó una persona y nadie revisó<br>• Con la costumbre que se cumple como si fuera ley<br>• Con la norma real que uno discute por no haberla leído"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Casi nada de lo que piden a un proyecto escolar está escrito<br>• Por eso se guarda <strong>quién lo pidió y cuándo</strong><br>• Y se cumple lo razonable sin dejar de preguntar la base"}},"emisor":{"nombre":"Quién lo emite","icon":"🏢","estructura":{"title":"Qué es","info":"• La <strong>oficina</strong> que firma y sella el papel<br>• No es la persona que atiende: es el cargo que firma<br>• Una recomendación no es una emisión"},"funcion":{"title":"Cómo se averigua","info":"• Se pregunta en la ventanilla más cercana, no en la más alta<br>• Se anota el <strong>nombre y el cargo</strong> de quien contesta<br>• Se confirma por escrito lo que dijo, aunque sea un correo"},"enfermedades":{"title":"Dónde se traba","info":"• Al pedirle el papel a quien solo puede opinar<br>• Al saltarse el nivel de abajo y volver con un aval que abajo molesta<br>• Con el cambio de titular, que reinicia la conversación"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• El permiso de aula lo da <strong>el centro</strong><br>• El aval para varios centros lo da <strong>el nivel de arriba</strong><br>• La constancia de una donación la emite <strong>el proyecto</strong>"}},"vigencia":{"nombre":"Hasta cuándo vale","icon":"📅","estructura":{"title":"Qué es","info":"• La <strong>fecha en que el papel deja de servir</strong><br>• A veces está escrita y a veces se deduce del año escolar<br>• Sin vigencia, un papel es una foto vieja"},"funcion":{"title":"Cómo se averigua","info":"• Se pregunta al emitirlo, no al necesitarlo<br>• Se apunta en el expediente <strong>desde cuándo y hasta cuándo</strong><br>• Se pone un recordatorio dos meses antes de que venza"},"enfermedades":{"title":"Dónde se traba","info":"• Con el papel de hace tres años que ya no lo reconoce nadie<br>• Con el cambio de autoridad, que en la práctica lo acorta<br>• Al pedir en septiembre lo que rendía pedido en enero"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• El año lectivo es la vigencia real de casi todo<br>• Lo del año escolar <strong>se vuelve a sacar en febrero</strong><br>• Un permiso de foto vence con la publicación para la que se pidió"}},"copia":{"nombre":"Dónde queda la copia","icon":"🗄️","estructura":{"title":"Qué es","info":"• El <strong>respaldo de lo entregado y de lo recibido</strong><br>• La copia sellada de lo que uno entregó vale más que la promesa de quien lo recibió<br>• El correo de confirmación también es copia"},"funcion":{"title":"Cómo se averigua","info":"• Al entregar se pide <strong>acuse</strong>: sello, firma y fecha en la copia<br>• Si no sellan, se manda el mismo día un correo resumiendo lo entregado<br>• Se guarda en una carpeta por centro, con la fecha en el nombre"},"enfermedades":{"title":"Dónde se traba","info":"• Al entregar sin quedarse con nada<br>• Al guardarlo todo en un teléfono que se pierde<br>• Al no anotar quién recibió, y no poder reclamar a nadie"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Una carpeta por centro y un archivo por trámite<br>• El correo de confirmación se guarda igual que un oficio<br>• Sin copia, el trámite se repite entero el año siguiente"}}};
let labParte='norma',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='📜 ¡'+name+' completó la Etapa 2 de la Ruta del Poder Político (Normas y trámites)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

